import{_ as i,I as a,c as t,o as l,ah as r,J as o}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"Online I Ching Reading: What Makes a Reading Useful?","description":"Online I Ching reading can be helpful or shallow. Learn what makes an online reading useful, and what to avoid.","frontmatter":{"title":"Online I Ching Reading: What Makes a Reading Useful?","description":"Online I Ching reading can be helpful or shallow. Learn what makes an online reading useful, and what to avoid."},"headers":[],"relativePath":"en/articles/online-i-ching-reading/index.md","filePath":"en/articles/online-i-ching-reading/index.md"}'),h={name:"en/articles/online-i-ching-reading/index.md"};function s(d,e,g,u,c,p){const n=a("SeoDownloadPanel");return l(),t("div",null,[e[0]||(e[0]=r('<h1 id="online-i-ching-reading-what-makes-a-reading-useful" tabindex="-1">Online I Ching Reading: What Makes a Reading Useful? <a class="header-anchor" href="#online-i-ching-reading-what-makes-a-reading-useful" aria-label="Permalink to “Online I Ching Reading: What Makes a Reading Useful?”">​</a></h1><p>There are many <strong>online I Ching reading</strong> tools now. Some are helpful. Many are too thin to be useful.</p><p>The question is not whether the reading happens online. The question is whether the structure of the reading is preserved.</p><h2 id="what-a-useful-online-i-ching-reading-should-include" tabindex="-1">What a useful online I Ching reading should include <a class="header-anchor" href="#what-a-useful-online-i-ching-reading-should-include" aria-label="Permalink to “What a useful online I Ching reading should include”">​</a></h2><p>A strong online reading should show:</p><ul><li>the original hexagram</li><li>moving lines</li><li>the changed hexagram</li><li>readable source text</li><li>some interpretive structure</li></ul><p>If it gives only one fortune-style paragraph, the reading is usually too shallow.</p><h2 id="why-context-matters" tabindex="-1">Why context matters <a class="header-anchor" href="#why-context-matters" aria-label="Permalink to “Why context matters”">​</a></h2><p>The best online readings help you move from:</p><ul><li>question</li><li>to cast</li><li>to structure</li><li>to interpretation</li></ul><p>That is much stronger than a random answer generator.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related guides”">​</a></h2><ul><li><a href="./../i-ching-ai/">I Ching AI</a></li><li><a href="./../how-to-read-i-ching/">How to Read the I Ching</a></li><li><a href="./../moving-lines/">Moving Lines Guide</a></li><li><a href="./../best-iching-app/">Best I Ching App</a></li></ul>',13)),o(n,{image:"/screenshots/ai-interpretation.png","image-alt":"Online I Ching reading screenshot",links:[{text:"I Ching AI",href:"../i-ching-ai/"},{text:"Moving Lines Guide",href:"../moving-lines/"},{text:"Best I Ching App",href:"../best-iching-app/"}]})])}const _=i(h,[["render",s]]);export{m as __pageData,_ as default};
